#include "UtilsSteam.h"

#include "base/Log.h"

namespace cc::Gs {

OnDiagnostic UtilsSteam::s_callback;
std::mutex UtilsSteam::s_mutex;
std::vector<DiagnosticMessage> UtilsSteam::s_messages;
bool UtilsSteam::s_acceptMessages = false;
uint64_t UtilsSteam::s_generation = 0;

void UtilsSteam::steamWarningHook(int severity, const char* msg) {
    CC_LOG_INFO("[Steam Warning] severity=%d: %s", severity, msg ? msg : "");
    const auto level = severity == 0 ? DiagnosticLevel::Info
        : (severity == 1 ? DiagnosticLevel::Warning : DiagnosticLevel::Unknown);
    enqueueDiagnostic({level, msg ? msg : ""});
}

void UtilsSteam::enqueueDiagnostic(DiagnosticMessage message) {
    // Never enter JS from an SDK callback; dispatch later from the platform pump.
    std::lock_guard<std::mutex> lock(s_mutex);
    if (s_acceptMessages && s_messages.size() < 256) s_messages.push_back(std::move(message));
}

void UtilsSteam::update() {
    std::vector<DiagnosticMessage> messages;
    {
        std::lock_guard<std::mutex> lock(s_mutex);
        messages.swap(s_messages);
    }
    const auto generation = s_generation;
    for (const auto& message : messages) {
        // Replacement listeners must not receive an old subscription's batch.
        if (generation != s_generation) break;
        s_callback.invoke(message);
    }
    // Warnings generated by listeners wait until the next pump.
}

void UtilsSteam::shutdown() {
    // Release the rooted JS warning hook while Steam is still alive, so the
    // static listener is not leaked past the session.
    ++s_generation;
    s_callback.reset();
    {
        std::lock_guard<std::mutex> lock(s_mutex);
        s_acceptMessages = false;
        s_messages.clear();
    }
    auto* utils = SteamUtils();
    if (utils) {
        utils->SetWarningMessageHook(nullptr);
    }
}

void UtilsSteam::setOnDiagnostic(OnDiagnostic callback) {
    ++s_generation;
    s_callback = std::move(callback);
    {
        std::lock_guard<std::mutex> lock(s_mutex);
        s_messages.clear();
        s_acceptMessages = static_cast<bool>(s_callback);
    }
    auto* utils = SteamUtils();
    if (utils) {
        if (s_callback) {
            utils->SetWarningMessageHook(&UtilsSteam::steamWarningHook);
            CC_LOG_INFO("[Steam] WarningMessageHook set");
        } else {
            utils->SetWarningMessageHook(nullptr);
            CC_LOG_INFO("[Steam] WarningMessageHook cleared");
        }
    }
}

} // namespace cc::Gs
